<?php require_once __DIR__.'/../app/layout.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT a.*,m.full_name,m.member_id FROM acknowledgements a JOIN members m ON m.id=a.member_id WHERE a.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Acknowledgement not found.');}if(!empty($_SESSION['member_id'])&&(int)$_SESSION['member_id']!==$r['member_id']){http_response_code(403);exit('Forbidden');}header_html('Acknowledgement');?><article class="card"><h1><?=e(setting($pdo,'org_name','TSSMT'))?></h1><h2>Acknowledgement</h2><p>No: <?=e($r['acknowledgement_no'])?><br>Date: <?=e($r['issued_at'])?></p><p>Received from <?=e($r['full_name'])?> (<?=e($r['member_id'])?>)<br>Payment type: <?=e(ucfirst($r['payment_type']))?><br>Amount: ₹<?=e($r['amount'])?></p><p><?=e(setting($pdo,'ack_footer'))?></p><p><?=e(setting($pdo,'authorised_signatory_name'))?><br><?=e(setting($pdo,'authorised_signatory_designation'))?></p><button onclick="window.print()">Print / Save PDF</button></article><?php footer_html();
